        env:
          LINUX_RESULT: ${{ needs.linux.result }}
          DESKTOP_RESULT: ${{ needs.desktop.result }}
        shell: bash
        run: |
          status=0
          rendered=0
          for os in ubuntu-24.04 macos-26-intel windows-latest; do
            result="$DESKTOP_RESULT"
            if [ "$os" = ubuntu-24.04 ]; then result="$LINUX_RESULT"; fi
            case "$result" in
              skipped) continue ;; # No shard was admitted; acceptance still rejects this producer.
              success|failure|cancelled) ;;
              *) echo "Unknown producer conclusion for $os: $result" >&2; status=1; continue ;;
            esac
            mkdir -p "../target/ui-report-blobs/$os"
            available=true
            shard_ids="$(node ../scripts/evals/chromium-evidence.mjs shards "$os")"
