      - run: npx playwright install --with-deps ${{ matrix.browser }}
      - name: Run real React portable workflows (mocked IPC boundary)
        run: node ../scripts/evals/portable-runner.mjs
        env:
          EVAL_BROWSER: ${{ matrix.browser }}
