pub(super) struct TestTiming {
    id: u64,
    started: std::time::Instant,
    phase: &'static str,
    enabled: bool,
    finished: bool,
    records: Vec<(&'static str, u128, u128)>,
    ports: Option<(u16, u16)>,
    omitted: usize,
}

#[cfg(test)]
impl TestTiming {
    pub(super) fn new(phase: &'static str) -> Self {
        static NEXT: std::sync::atomic::AtomicU64 = std::sync::atomic::AtomicU64::new(1);
        let mut timing = Self {
            id: NEXT.fetch_add(1, std::sync::atomic::Ordering::Relaxed),
            started: std::time::Instant::now(),
            phase,
            enabled: std::env::var("MESH_TALK_TEST_TIMING").as_deref() == Ok("1"),
            finished: false,
            records: Vec::new(),
            ports: None,
            omitted: 0,
        };
        timing.mark(phase);
        timing
    }

    pub(super) fn mark(&mut self, phase: &'static str) {
        if self.enabled {
            static EPOCH: std::sync::OnceLock<std::time::Instant> = std::sync::OnceLock::new();
            if self.records.len() == 32 {
                self.records.remove(0);
                self.omitted += 1;
            }
            self.records.push((
                phase,
                self.started.elapsed().as_micros(),
                EPOCH
                    .get_or_init(std::time::Instant::now)
                    .elapsed()
                    .as_micros(),
            ));
        }
    }

    pub(super) fn phase(&mut self, phase: &'static str) {
        self.phase = phase;
        self.mark(phase);
    }

    pub(super) fn finish(&mut self) {
        self.mark("complete");
        self.finished = true;
    }

    pub(super) fn socket(&mut self, stream: &tokio::net::TcpStream) {
        if self.enabled
            && let (Ok(local), Ok(remote)) = (stream.local_addr(), stream.peer_addr())
        {
            self.ports = Some((local.port(), remote.port()));
        }
    }
}

#[cfg(test)]
impl Drop for TestTiming {
    fn drop(&mut self) {
        if !self.finished {
            self.mark("dropped");
        }
        if self.enabled {
            use std::fmt::Write;
            let mut output = String::new();
            let _ = writeln!(
                output,
                "test-timing id={} finished={} last_phase={} omitted={} ports={:?}",
                self.id, self.finished, self.phase, self.omitted, self.ports
            );
            for (phase, elapsed, tick) in &self.records {
                let _ = writeln!(
                    output,
                    "test-timing id={} phase={phase} elapsed_us={elapsed} tick_us={tick}",
                    self.id
                );
            }
            // One stderr lock per bounded span, never one per protocol phase.
            eprint!("{output}");
        }
    }
}

#[derive(Clone, Copy, Debug)]
enum FilePhase {
    Dial,
    Manifest,
    ManifestCustody,
    Consent,
    ConsentWait,
    InitialCustody,
        run: cargo build --workspace --locked

      # Linux/Windows own complete instrumented workspace coverage. macOS keeps
      # desktop-specific Host coverage (including native updater policy) and runs
      # every remaining workspace target normally, avoiding a duplicate costly
      # instrumented Core test build. No platform repeats its test suite.
      - name: Test + coverage (macOS)
        if: matrix.os != 'ubuntu-latest'
        working-directory: src-tauri
        shell: bash
        env:
          RUST_TEST_THREADS: 4
          NEXTEST_TEST_THREADS: 4
        run: |
          bash ../scripts/ci/workspace-coverage.sh macos
          # llvm-cov runs Host; Nextest runs the remaining default targets.
          # Stable Rust doctests retain their original separate check.
          cargo test --workspace --doc

      - name: Test + coverage (Linux)
        if: matrix.os == 'ubuntu-latest'
        working-directory: src-tauri
        shell: bash
        run: bash ../scripts/ci/workspace-coverage.sh linux

      - name: Workspace doctests (Linux)
        if: matrix.os == 'ubuntu-latest'
        run: cargo test --workspace --doc --locked

      - name: Multi-process core evidence and coverage (Linux)
        if: matrix.os == 'ubuntu-latest'
      - name: Preserve Linux native crash diagnostics
        if: always() && runner.os == 'Linux'
        uses: actions/upload-artifact@v7
        with:
          name: native-crash-linux-${{ github.run_attempt }}
          path: ${{ runner.temp }}/native-crash-diagnostics/reports/
          if-no-files-found: warn
          retention-days: 14

      - name: Upload test timing diagnostics
        if: always() && env.MESH_TALK_TEST_TIMING == '1'
        uses: actions/upload-artifact@v7
        with:
          name: test-timing-${{ matrix.os }}-${{ github.run_attempt }}
          path: ${{ runner.temp }}/mesh-talk-test-timing.log
          if-no-files-found: warn

      - name: Upload coverage to Codecov
        # Dependabot PRs to dev cannot read the Actions CODECOV_TOKEN secret.
        # Their tests still run; only the unauthenticated upload is skipped.
        if: >-
                && exact_private_receipt(&reference, &owner, group, id, &requester, &source)
            {
                break (requester, source);
            }
            tokio::time::sleep(Duration::from_millis(20)).await;
        }
    })
    .await;
    record_b_trace(
        &abort_trace,
        b_clock,
        "fixture",
        if receipt.is_ok() {
            "A_private_receipt"
        } else {
            "A_deadline_expired"
        }
        .into(),
    );
    if std::env::var_os("MESH_TALK_OPERATION_TRACE").is_some()
