        if: always()
        uses: actions/upload-artifact@v7
        with:
          name: ai-eval-report
          path: target/ai-eval/
          if-no-files-found: error

  provider-status:
    name: Report AI provider availability (not an eval result)
    runs-on: ubuntu-latest
    outputs:
      configured: ${{ steps.provider.outputs.configured }}
    steps:
      - name: Disclose whether real model evaluation can run
        id: provider
        env:
          AI_EVAL_COMMAND: ${{ secrets.AI_EVAL_COMMAND }}
        run: |
          if [ -n "${AI_EVAL_COMMAND:-}" ]; then
            echo 'configured=true' >> "$GITHUB_OUTPUT"
            echo 'Real-model provider configured; evaluation verdict comes from the separate job.' >> "$GITHUB_STEP_SUMMARY"
          else
            echo 'configured=false' >> "$GITHUB_OUTPUT"
            echo 'Real-model evaluation NOT RUN: provider unavailable. Deterministic contracts are not model-backed eval evidence.' >> "$GITHUB_STEP_SUMMARY"
          fi
        run: |
          npm ci
          npm run build

      # The shared runner contract passed before these shards started.
      - name: Mutants (workspace sample)
        if: steps.selection.outputs.selected != '0'
        working-directory: src-tauri
        run: node ../scripts/release/run-mutants.mjs

      - name: Upload mutants report
        # A test-only/config-only diff can exit successfully without creating a report.
        if: always() && hashFiles('mutants.out/**') != ''
        uses: actions/upload-artifact@v7
        with:
          name: mutants-report-${{ matrix.worker }}
          path: mutants.out/
          if-no-files-found: error

  # Preserve the stable branch-protection check across matrix size changes.
  mutation-gate:
    name: mutants
    needs: [runner-contract, mutants]
    if: ${{ !cancelled() }}
    runs-on: ubuntu-latest
    timeout-minutes: 5
    permissions:
      id-token: write # OIDC, to publish results to the OpenSSF API (badge)
    steps:
      - name: Checkout
        uses: actions/checkout@3d3c42e5aac5ba805825da76410c181273ba90b1 # v7.0.1
        with:
          persist-credentials: false

      - name: Run analysis
        uses: ossf/scorecard-action@v2.5.0
        with:
          results_file: results.sarif
          results_format: sarif
          publish_results: true # feeds the public badge at api.securityscorecards.dev

      - name: Upload SARIF artifact
        uses: actions/upload-artifact@v7
        with:
          name: scorecard-results
          path: results.sarif
          retention-days: 5
